const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export const REEFS=['Paper Moon Cove','The Kelp Library','Amber Archway','Jelly Lanterns','Glasswater Maze','Starlit Sanctuary'];
export class Inkfin{
 constructor({players=1,level=1,difficulty=3}={}){this.level=clamp(Math.round(level),1,6);this.difficulty=clamp(Math.round(difficulty),1,5);this.count=players===2?2:1;this.clock=0;this.limit=160-this.difficulty*8;this.done=false;this.won=false;this.events=[];this.home={x:910,y:290,r:65};this.needed=8;this.fish=Array.from({length:10},(_,i)=>({id:i,x:95+i%3*22,y:200+Math.floor(i/3)*37,vx:0,vy:0,rescued:false,stun:0,hits:0}));this.lures=Array.from({length:this.count},()=>({x:100,y:280,active:false,repel:false,energy:100}));this.rocks=[{x:340,y:100,r:60},{x:360,y:460,r:72},{x:610,y:270+(this.level%2?95:-85),r:70},...(this.level>3?[{x:770,y:460,r:55}]:[])];this.vents=[{x:210,y:310},{x:540,y:100}];this.saved=0;}
 lure(owner,x,y,active=true,repel=false){const l=this.lures[owner];if(!l||this.done)return;l.x=clamp(x,20,980);l.y=clamp(y,30,530);l.active=active;l.repel=repel;}
 jelly(i){return{x:440+i*210+Math.sin(this.clock*.5+i)*55,y:260+Math.sin(this.clock*.7+i*2)*125,r:23};}
 update(dt){if(this.done||dt<=0)return;dt=Math.min(dt,1/30);this.clock+=dt;for(const l of this.lures){const refill=this.vents.some(v=>Math.hypot(l.x-v.x,l.y-v.y)<60);l.energy=clamp(l.energy+dt*(l.active&&!refill?-5.5:refill?28:14),0,100);}const old=this.fish.map(f=>({...f}));for(const f of this.fish){if(f.rescued)continue;f.stun=Math.max(0,f.stun-dt);let ax=5*Math.sin(this.clock*.6+this.level),ay=4*Math.cos(this.clock*.4+f.id*.2);for(const l of this.lures){if(!l.active||l.energy<1)continue;const dx=l.x-f.x,dy=l.y-f.y,d=Math.hypot(dx,dy)||1;if(d<250){const force=l.repel?-220:150;ax+=dx/d*force*Math.min(1,d/45);ay+=dy/d*force*Math.min(1,d/45);}}let nx=0,ny=0,n=0;for(const other of old){if(other.id===f.id||other.rescued)continue;const dx=f.x-other.x,dy=f.y-other.y,d=Math.hypot(dx,dy)||1;if(d<23){ax+=dx/d*100;ay+=dy/d*100;}else if(d<95){nx+=other.vx;ny+=other.vy;n++;}}if(n){ax+=(nx/n-f.vx)*.6;ay+=(ny/n-f.vy)*.6;}for(const rock of this.rocks){const dx=f.x-rock.x,dy=f.y-rock.y,d=Math.hypot(dx,dy)||1;if(d<rock.r+38){ax+=dx/d*280;ay+=dy/d*280;}if(d<rock.r+9){f.x=rock.x+dx/d*(rock.r+9);f.y=rock.y+dy/d*(rock.r+9);f.vx*=.3;f.vy*=.3;}}for(let i=0;i<Math.ceil(this.level/2);i++){const j=this.jelly(i);if(!f.stun&&Math.hypot(f.x-j.x,f.y-j.y)<j.r+12){f.stun=1.8;f.hits++;f.vx=-80;f.vy=(f.id%2?1:-1)*50;this.events.push({type:'startle',x:f.x,y:f.y});}}const limit=f.stun?55:90-this.difficulty*3;f.vx=(f.vx+ax*dt)*Math.exp(-1.2*dt);f.vy=(f.vy+ay*dt)*Math.exp(-1.2*dt);const speed=Math.hypot(f.vx,f.vy);if(speed>limit){f.vx*=limit/speed;f.vy*=limit/speed;}f.x=clamp(f.x+f.vx*dt,20,980);f.y=clamp(f.y+f.vy*dt,30,530);if(Math.hypot(f.x-this.home.x,f.y-this.home.y)<this.home.r){f.rescued=true;this.saved++;this.events.push({type:'rescue',x:f.x,y:f.y});}}if(this.saved>=this.needed){this.done=true;this.won=true;}else if(this.clock>=this.limit)this.done=true;}
 score(){return Math.max(0,this.saved*200-this.fish.reduce((n,f)=>n+f.hits*8,0)+(this.won?Math.round((this.limit-this.clock)*5):0));}
}
